\label{continuation of |x|} The distribution $||x||_{p}^{s}$, $\text{Re} 
(s)>0$, admits the following meromorphic continuation,
\begin{align*}
\left\langle ||x||_{p}^{s},\varphi(x)\right\rangle  &  =\frac{1-p^{-n}
}{1-p^{-s -n}}\varphi(0)+ \int_{||x||_{p}>1}||x||_{p}^{s} \varphi(x)\,dx\\
&  +\int_{||x||_{p}\leq1}||x||_{p}^{s} (\varphi(x)-\varphi(0))\,dx,
\quad\varphi\in S.
\end{align*}
In particular, all the poles of $||x||_{p}^{s}$ have real part equal to $-n$.

\label{elliptic = Taibleson} Let $f(x)\in\mathbb{Q}_{p}[x]$, $x=(x_{1} 
,\dotsc,x_{n})$, be an elliptic polynomial of degree $d$. Then
\[
|f|_{p}^{s}=\frac{(1-p^{ds})L(p^{-s})}{(1-p^{-n})(1-p^{-ds-n})}\mathit{R} 
_{ds+n},\quad s\in\mathbb{C} 
\]
as distributions on $\mathcal{W}$. Here $L(p^{-s})$ is the numerator of
$Z(s,f)$ which is a polynomial in $p^{-s}$ with rational coefficients.

\label{fund solu Tai} A fundamental solution of (\ref{eq pseudo}) is
\[
E_{\alpha}(x)= 
\begin{cases}
\dfrac{1-p^{-\alpha}}{1-p^{\alpha-n}}||x||_{p}^{\alpha-n} & \text{ if
$\alpha\neq n$}\\
\dfrac{1-p^{n}}{p^{n}\ln p}\ln(||x||_{p}) & \text{ if $\alpha=n$.} 
\end{cases}
\]

\label{Lemma 6} For any $\alpha>0$ and $l\geq0$, the mapping $f(D,\alpha
):H^{l+d\alpha}\rightarrow H^{l}$ is a well-defined continuous mapping between
Banach spaces.

Let $\phi\in S$. Since $f(D,\alpha)$ is an elliptic operator, by Lemma
\ref{Lemma 1}, we have that
\begin{align*}
||f(D,\alpha)\phi||_{H^{l}}^{2}  &  =\int_{\mathbb{Q}_{p}^{n}}[\text{max} 
(1,||\xi||_{p})]^{2l}|f(\xi)|^{2\alpha}|\mathcal{F}(\phi)(\xi)|^{2}\,d\xi\\
&  \leq C_{1}\int_{\mathbb{Q}_{p}^{n}}[\text{max}(1,||\xi||_{p})]^{2(l+\alpha
)}|\mathcal{F}(\phi)(\xi)|^{2}\,d\xi=C_{1}||\phi||_{H^{l+\alpha}}^{2}.
\end{align*}
The result follows from the fact that $S$ is dense in $H^{l+d\alpha}$.

Let $v\in\mathcal{S}$, then $v=v_{\mathcal{W}}+v_{\mathcal{L}}$, where
$v_{\mathcal{W}}\in\mathcal{W}$ and $v_{\mathcal{L}}\in\mathcal{L}$. Thus, in
order to prove the existence of a solution $u$, it is sufficient to show that
the two following equations have solutions:
\begin{equation}
f(D,\alpha)u_{\mathcal{W}}=v_{\mathcal{W}}, \label{Eq v_W} 
\end{equation} 
\begin{equation}
f(D,\alpha)u_{\mathcal{L}}=v_{\mathcal{L}}. \label{Eq v_L} 
\end{equation}


We first consider equation (\ref{Eq v_W}). By Theorem \ref{fund solu ellip},
$u_{\mathcal{W}}=E_{\alpha}\ast v_{\mathcal{W}}$ is a solution of
(\ref{Eq v_W}), and by Corollary \ref{cor1}, we have 

\begin{align*}
||u_{\mathcal{W}}||_{H^{l+d\alpha}}^{2}  &  =\int_{\mathbb{Q}_{p}^{n} 
}[\text{max}(1,||\xi||_{p})]^{2(l+d\alpha)}|\mathcal{F}(E_{\alpha}\ast
v_{\mathcal{W}})(\xi)|^{2}\,d\xi\\
&  =C(\alpha,d,n)\int_{\mathbb{Q}_{p}^{n}}[\text{max}(1,||\xi||_{p} 
)]^{2(l+d\alpha)}|\left\Vert \xi\right\Vert _{p}^{-2d\alpha}|\mathcal{F} 
(v_{\mathcal{W}})(\xi)|^{2}\,d\xi\\
&  =C(\alpha,d,n)\Bigl\{\int_{||\xi||_{p}\leq1}||\xi||_{p}^{-2d\alpha
}|\mathcal{F}(v_{\mathcal{W}})(\xi)|^{2}\,d\xi\\
&  \hspace{1cm}+\int_{||\xi||_{p}>1}||\xi||_{p}^{2l}|\mathcal{F} 
(v_{\mathcal{W}})(\xi)|^{2}\,d\xi\Bigr\}.
\end{align*}


We now recall that $v_{\mathcal{W}}(\xi)=p^{rn}C\chi_{r}(\xi)$, with $r>0$.
Then, $\mathcal{F}(v_{\mathcal{W}})(\xi)=C\chi_{-r}(\xi)$ and
\begin{align*}
||u_{\mathcal{W}}||_{H^{l+d\alpha}}^{2} &  \leq C(\alpha,d,n)\Bigl\{C^{2} 
p^{2rn}\int\limits_{||\varepsilon||_{p}\leq1}||\varepsilon||_{p}^{-2d\alpha
}\,d\varepsilon\\
&  \hspace{2.5cm}+||v_{\mathcal{W}}||_{H^{l}}^{2}\Bigr\}\\
&  \leq C(\alpha,d,n)\Bigl\{C_{1}(\alpha,d,n)+||v_{\mathcal{W}}||_{H^{l}} 
^{2}\Bigr\},
\end{align*}
since $-2d\alpha>-n$, cf. Remark \ref{remark3}. Therefore $u_{\mathcal{W}}\in
H^{l+d\alpha}$.

We now consider equation (\ref{Eq v_L}). Since
\[
\mathcal{F}(u_{\mathcal{L}})=\mathcal{F}(v_{\mathcal{L}})|f|_{p}^{-\alpha},
\]
and $f$ is elliptic,
\[
|\mathcal{F}(u_{\mathcal{L}})(\xi)|\leq C||\xi||^{-d\alpha}|\mathcal{F}
(v_{\mathcal{L}})(\xi)|, \text{(cf. Lemma \ref{Lemma 1})}.
\]
Then,
\begin{align*}
||u_{\mathcal{L}}||_{H^{l+d\alpha}}^{2}  &  \leq\int_{||\xi||_{p}\leq1} 
||\xi||_{p}^{-2d\alpha}|\mathcal{F}(v_{\mathcal{L}})(\xi)|^{2}\,d\xi\\
&  \hspace{1cm}+\int_{||\xi||_{p}>1}||\xi||_{p}^{2l}|\mathcal{F} 
(v_{\mathcal{L}})(\xi)|^{2}\,d\xi.
\end{align*}


The second integral is bounded by $||v_{\mathcal{L}}||_{H^{l}}^{2}$. For the
first integral, we observe that if $0<\alpha<n/2d$, then
\[
\int_{||\xi||_{p}\leq1}||\xi||_{p}^{-2d\alpha}|\varphi(\xi)|^{2}\,d\xi\leq
C||\varphi||_{L^{2}},
\]
for any $\varphi\in S$. Therefore,
\[
||u_{\mathcal{L}}||_{H^{l+d\alpha}}^{2}\leq C||\mathcal{F}(v_{\mathcal{L} 
})||_{L^{2}}+||v_{\mathcal{L}}||_{H^{l}}^{2}.
\]


In this way, we established the existence of $u\in H^{l+d\alpha}$ which is
uniformly continuous, by Lemma \ref{Sobolev embedding Lemma}, such that
$f(D,\alpha)u=v$, for any $v\in S$. Finally, we show that $u$ is unique.
Indeed, if $f(D,\alpha)u^{\prime}=v$, then
\[
f(D,\alpha)(u-u^{\prime})=0,\qquad\text{i.e., }|f|_{p}^{\alpha}\mathcal{F} 
(u-u^{\prime})=0,
\]
and thus $\mathcal{F}(u-u^{\prime})(\xi)=0$ if $\xi\neq0$, since $f$ is
elliptic. Then $\Psi(x\cdot\xi)(u-u^{\prime})(\xi)=0$ almost everywhere, and a
fortiori $(u-u^{\prime})(\xi)=0$ almost everywhere, and by the continuity of
$u-u^{\prime}$, $u(\xi)=u^{\prime}(\xi)$ for any $\xi\in\mathbb{Q}_{p}^{n}$.

\label{lemma3}For any, $\alpha>0$, $l\geq0$, the mapping $f(D,\alpha
):\mathcal{H}^{l+d\alpha}\rightarrow\mathcal{H}^{l}$ is a well-defined
continuous mapping between Banach Spaces.

By Lemma \ref{lemma3}, the mapping is well-defined. Let $v\in\mathcal{W}^{l}$,
and let $\{v_{n}\}$ a Cauchy sequence in $\mathcal{W}$ converging to $v$. By
Theorem \ref{fund solu ellip}, there exits a sequence $\{u_{n}\}$ in
$H^{l+d\alpha}$ such that $f(D,\alpha)u_{n}=v_{n}$. We now show that
$\{u_{n}\}$ is a Cauchy sequence in $\mathcal{H}^{l+d\alpha}$ as follows:
\begin{align*}
||u_{n}-u_{m}||_{\mathcal{H}^{l+d\alpha}}^{2}  &  \leq C\int_{\mathbb{Q} 
_{p}^{n}}||\xi||_{p}^{2(l+d\alpha)}||\xi||_{p}^{-2d\alpha}|\mathcal{F} 
(v_{n}-v_{m})(\xi)|^{2}\,d\xi\\
&  \leq C||v_{n}-v_{m}||_{\mathcal{H}^{l}}^{2}.
\end{align*}
Thus, there exists $u\in\mathcal{H}^{l+d\alpha}$ such that $u_{n}\rightarrow
u$, and by the continuity of $f(D,\alpha)$, $f(D,\alpha)u=v$.
